create or replace function internal.has_role(allowed_roles text[]) returns boolean language plpgsql stable security definer set search_path = public as $$ begin return exists (select 1 from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active' and s.role = any(allowed_roles)); end; $$;
create or replace function internal.current_user_role() returns text language plpgsql stable security definer set search_path = public as $$ declare v_role text; begin select s.role into v_role from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active' limit 1; return v_role; end; $$;
create or replace function internal.is_active_member() returns boolean language plpgsql stable security definer set search_path = public as $$ begin return exists (select 1 from public.staff s where (s.user_id = (select auth.uid()) or (s.user_id is null and lower(s.email) = lower((select auth.jwt() ->> 'email')))) and s.status = 'active'); end; $$;
